const note = sticky("## Marketing — Ad Actions (the only door to Meta)\nThe daily Claude routine decides; this fixed workflow checks and acts. No AI model calls Meta directly.\n\n**State** (`mode: \"state\"`): reads campaigns + ad sets, returns campaign-level budgets and the ACTIVE daily total. Read-only, no ledger rows.\n\n**Action** (one per run): ledger row for the same key → live object + account budgets from Meta → Guard (`apGuardAdAction` from `agents/marketing/autopilot.js`: live mode, caps, ≤20% raise, budget unchanged since the plan, never above the daily maximum, no duplicate key) → POST to Meta → read back → ledger row (done / failed). Refusals are logged with their own key (`…|refused|<ts>`, kind `ad_refused`) so they never block a later valid action.\n\nKept **unpublished** on purpose (no public URL): run through n8n MCP `execute_workflow` (manual, webhookData). Meta credential: Facebook Graph API with a System User token (ads_management). Source of truth: `ceo-brain/workflows/marketing-ad-actions/build.js` — never hand-edit the Code nodes.", [adActionIn, readRequest, readCampaigns, readAdSets], { color: 4 });

export default workflow('marketing-ad-actions', 'Marketing — Ad Actions')
  .add(adActionIn)
  .to(readRequest)
  .to(readCampaigns)
  .to(readAdSets)
  .to(routeMode
    .onTrue(buildState)
    .onFalse(readLedger.to(readLive).to(guard).to(allowed
      .onTrue(applyMeta.to(readBack).to(confirm).to(writeLedger))
      .onFalse(writeLedger))))
  .add(writeLedger)
  .to(result)
  .add(note)
  .group('Read request + Meta', [readRequest, readCampaigns, readAdSets], { description: 'Normalise the body, then read all campaigns and ad sets of the ad account (read-only).' })
  .group('Final check', [readLedger, readLive, guard], { description: 'Same key in the ledger? Live object re-read. apGuardAdAction decides with the live budget.' })
  .group('Apply + confirm', [applyMeta, readBack, confirm], { description: 'The one write to Meta, then read it back and mark done or failed.' })
  .group('Ledger + answer', [writeLedger, result], { description: 'One ledger row (done, failed or refused with its own key) and the answer for the routine.' });
